export type UncertaintyMeasurement = { questionId: string, sceneId: string, 
/**
 * Original probabilities, ordered by stable outcome ID; never inferred.
 */
outcomes: Array<HypothesisProbability>, probabilitySum: number, entropyBits: number, 
/**
 * H / log2(declared outcome count), including declared zero-probability outcomes.
 */
normalizedEntropy: number, effectiveOutcomes: number, outcomeCount: number, positiveOutcomeCount: number, 
/**
 * Current H minus the previous supplied H for this question in presentation order.
 */
entropyChangeBits: number | null, };
